--- /dev/null
+++ b/benchmarks/prefill.py
@@ -0,0 +1,86 @@
+#!/usr/bin/env python3
+"""Compare two binaries on prompt throughput; eight decode tokens check handoff."""
+import argparse
+import json
+import subprocess
+import time
+from pathlib import Path
+
+from run import ROOT, digest, parse_metrics, power
+
+
+def main():
+    parser = argparse.ArgumentParser(description=__doc__)
+    parser.add_argument('--before', type=Path, required=True)
+    parser.add_argument('--after', type=Path, required=True)
+    parser.add_argument('--model', type=Path, required=True)
+    parser.add_argument('--out', type=Path, required=True)
+    parser.add_argument('--rounds', type=int, default=2)
+    args = parser.parse_args()
+    if args.rounds < 1:
+        parser.error('--rounds must be positive')
+    args.out.mkdir(parents=True, exist_ok=True)
+    report_path = args.out / 'report.json'
+    if report_path.exists():
+        parser.error('output already contains a report; choose a new directory')
+    binaries = {key: path.resolve() for key, path in [('before', args.before), ('after', args.after)]}
+    sentence = 'The quick brown fox jumps over the lazy dog. Each sentence is part of a repeated document used to measure prompt processing.\n'
+    prompts = {str(n): sentence * n + '\nSummarize this document in three sentences.' for n in [4, 20, 128]}
+    report = {
+        'binaries': {k: {'path': str(p), 'sha256': digest(p)} for k, p in binaries.items()},
+        'source_commit': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
+        'source_diff': subprocess.check_output(['git', 'diff', 'HEAD'], cwd=ROOT, text=True),
+        'prompts': prompts,
+        'notes': [
+            'Fresh processes, max_ctx=8192, adaptive pool, two adaptive drafts, no prefix cache.',
+            'Exactly eight decode tokens; this suite measures prefill, not complete answers or decode throughput.',
+            'Loading/conversion excluded; any store build invalidates the sample.',
+            'Power sampled at process boundaries; brief intervening changes may be missed.',
+            'Configurations and binary order rotate. Existing OS file caches are not purged.',
+            'Low-bit prefill changes output relative to the earlier Q4-prefill implementation.',
+        ],
+        'runs': [],
+    }
+    for round_index in range(args.rounds):
+        bits_order = [4, 3, 2]
+        bits_order = bits_order[round_index % 3:] + bits_order[:round_index % 3]
+        for length, prompt in prompts.items():
+            for bits in bits_order:
+                order = ['before', 'after'] if round_index % 2 == 0 else ['after', 'before']
+                for label in order:
+                    name = f'r{round_index + 1}-repeat{length}-q{bits}-{label}'
+                    command = [str(binaries[label]), str(args.model.resolve()), prompt,
+                               '--experts', str(bits), '--max-ctx', '8192', '--max-tokens', '8', '--no-eos']
+                    before = power()
+                    if before['source'] != 'ac':
+                        raise RuntimeError('benchmark requires AC power')
+                    start = time.monotonic()
+                    result = subprocess.run(command, cwd=ROOT, text=True, capture_output=True, timeout=300)
+                    after = power()
+                    row = {'id': name, 'round': round_index + 1, 'binary': label, 'bits': bits,
+                           'prompt': length, 'wall_seconds': time.monotonic() - start,
+                           'power_before': before, 'power_after': after,
+                           'exit_code': result.returncode, 'stderr': result.stderr,
+                           'output': name + '.txt', 'valid': False}
+                    (args.out / row['output']).write_text(result.stdout)
+                    try:
+                        if result.returncode:
+                            raise ValueError('engine failed')
+                        row['metrics'] = parse_metrics(result.stderr)
+                        if row['metrics']['store_build_seconds'] is not None:
+                            raise ValueError('sample built a store')
+                        if after['source'] != 'ac':
+                            raise ValueError('power changed')
+                        row['valid'] = True
+                    except ValueError as error:
+                        row['error'] = str(error)
+                    report['runs'].append(row)
+                    report_path.write_text(json.dumps(report, indent=2) + '\n')
+                    metrics = row.get('metrics', {})
+                    print(f"{name}: {metrics.get('prompt_tokens')} tokens, {metrics.get('pp_s')} PP/s, valid={row['valid']}", flush=True)
+                    if not row['valid']:
+                        raise RuntimeError(f'{name}: {row["error"]}; details saved in {report_path}')
+
+
+if __name__ == '__main__':
+    main()
